refs += [dict(id='original_full',title='An Operational Characterization of Mutual Information in Algorithmic Information Theory',authors='Andrei Romashchenko; Marius Zimand',year=2019,url='https://doi.org/10.1145/3356867',pdf_url='https://arxiv.org/pdf/1710.05984',locator='JACM 66(5), 2019; full arXiv v5 submitted 29 April 2019, PDF dated 30 April. Section 6, Theorem 6.1; Section 9, Open Question 1. Earlier conference version is the primary reference.'),dict(id='solution',title='Communication Complexity of the Secret Key Agreement in Algorithmic Information Theory',authors='Emirhan Gürpınar; Andrei Romashchenko',year=2020,url='https://doi.org/10.4230/LIPIcs.MFCS.2020.44',pdf_url='https://drops.dagstuhl.de/storage/00lipics/lipics-vol170-mfcs2020/LIPIcs.MFCS.2020.44/LIPIcs.MFCS.2020.44.pdf',locator='Theorem 2 and introduction’s explicit answer to the earlier Open Question 1; this conference version assumes polynomially many private random bits.'),dict(id='solution_full',title='Communication Complexity of the Secret Key Agreement in Algorithmic Information Theory',authors='Emirhan Gürpınar; Andrei Romashchenko',year=2024,url='https://doi.org/10.1145/3665163',pdf_url='https://arxiv.org/pdf/2004.13411v6',locator='ACM Transactions on Computation Theory 16(3), online 10 September 2024, print 30 September. Full arXiv v6 submitted 9 May 2024, PDF dated 13 May: Theorem 2, Proposition 1 and Section 6. Removes the polynomial-randomness restriction. Publication dates checked against publisher-deposited Crossref metadata.')]
save(i,dict(title='Private randomness in algorithmic secret-key agreement',formal='Historical question, answered by the 2020 follow-up and its expanded 2024 version: does the worst-case communication barrier min{C(x|y),C(y|x)}−O(log n) for secret-key agreement persist when Alice and Bob use independent private random bits? The answer is affirmative for the bounded-error secret-key task below. In particular, on a hard family of pairs of n-bit inputs with C(x|y), C(y|x) and I(x:y) all equal to n/2 within O(log n), every uniformly computable protocol that succeeds on the promised inputs with probability greater than 1/2 has worst-case communication at least n/2−O(log n). This holds even for a secret key of length δ(n)=ω(log n), instead of the maximal length I(x:y)−O(log n). The follow-up explicitly identifies this as its answer to the source’s Open Question 1.',definitions='Fix an optimal plain universal description machine U and a computable encoding of tuples. C(x|y) is the minimum bit length of a program p with U(p,y)=x; C(x)=C(x|empty string), C(x,y)=C(⟨x,y⟩), and I(x:y)=C(x)+C(y)−C(x,y). Alice receives x∈{0,1}ⁿ and Bob receives y∈{0,1}ⁿ. Both additionally receive the exact complexity profile p=(C(x),C(y),C(x,y)); the profile and the fixed protocol are public. This small auxiliary input is supplied, not computed from x or y. The parties use independent fair private coin sequences, independent of the fixed input pair. They exchange messages on a public noiseless channel, then separately output strings z_A,z_B. The transcript t records all publicly communicated bits and their order; actual transmitted framing is charged too. Cost is the worst-case total number of communicated bits over legal inputs and coin outcomes, not its expectation. The same finite algorithms compute messages and outputs for all n. Local computation and the number of interaction rounds have no polynomial bound; the protocol must terminate on every input and coin outcome, even for invalid auxiliary profiles, where output correctness is not required. The expanded result permits any finite number of private random bits, without a polynomial bound in n. Success means z_A=z_B=z of the requested length and C(z|t,p)≥|z|−O(log n), so agreement on a public string does not qualify as secrecy. Probability is over the private coins, separately for each promised input pair; x,y need not come from an independent, identically distributed or computable source. The hard-family profile equalities and lower bound mean additive deviations bounded by fixed multiples of log₂(n+2) for sufficiently large n; these constants can depend on U and the fixed protocol, not on n or its coin outcomes. The notation δ(n)=ω(log n) means δ(n)/log₂(n+2)→∞. Only attainable secret-key lengths are relevant; the maximal length is I(x:y) up to logarithmic terms.',question_type='yes_no',answer_criterion='The historical communication-barrier question is settled for bounded-error secret-key agreement by the follow-up’s Theorem 2, together with the earlier matching upper bound. The recorded quantitative theorem has success probability greater than 1/2 and incompressible secret keys. The original Theorem 7 was phrased more generally using arbitrary positive constant success probability and a lower bound directly on conditional key complexity; this review does not claim that the follow-up’s displayed theorem reproduces every such parameter verbatim. It records the follow-up’s explicit resolution of the usual secret-key task and its precise scope.',context_blocks=[dict(title='Mutual information is achievable as a secret key',text='The original paper gives a protocol producing a shared secret of length I(x:y) within logarithmic precision using min{C(x|y),C(y|x)}+O(log n) communication. Both parties know the complexity profile. The unresolved issue in the extracted passage was the matching communication lower bound with private coins, not the achievable key length.',citation='original_full'),dict(title='Private coins require a separate lower bound',text='In the public-coin model the eavesdropper sees the random string as well as the communication, so secrecy is conditioned on both. Private coins are hidden unless communicated. They cannot simply be declared public without changing the secrecy requirement.',citation='primary'),dict(title='The later result answers the cited question',text='The MFCS 2020 introduction explicitly points to the earlier Open Question 1 and gives an affirmative answer. Its Theorem 2 shows a sharp worst-case threshold even when only a superlogarithmic secret key is requested, initially with polynomially many private random bits.',citation='solution'),dict(title='The unrestricted-randomness version is later',text='The expanded 2024 text removes that randomness restriction and supplies full proofs. The bound concerns worst-case input pairs: the same paper exhibits other pairs with similar complexity profiles for which shorter secret keys need less communication. A lower bound for every individual pair is not asserted.',citation='solution_full')],why='Establishes that hidden local randomness cannot remove the worst-case communication needed to turn algorithmic correlation into a shared secret. This isolates communication as a resource distinct from computational hardness and from the amount of mutual information.',references=refs,progress=[dict(date='2018',text='Theorem 7 proves the public-randomness lower bound; Open Question 1 asks about private randomness.',citation='primary'),dict(date='2020',text='MFCS Theorem 2 establishes the private-coin worst-case bound with polynomial randomness and identifies it as an answer to the original question.',citation='solution'),dict(date='2024-05-09',text='Full arXiv v6 supplies unrestricted-randomness treatment; its PDF is dated 13 May 2024.',citation='solution_full'),dict(date='2024-09-10',text='Expanded result published online in ACM Transactions on Computation Theory.',citation='solution_full')],status='resolved',status_note='Read the original conference and full 2019 formulations, the MFCS 2020 theorem, and the expanded May 2024 text’s Theorem 2, Proposition 1, model and conclusion. Matched the private-coin setting, supplied complexity profile, secrecy, uniformity, worst-case cost and removal of the randomness cap. The later authors explicitly state that they answer the cited open question. The displayed later theorem uses success greater than1/2; no literal all-parameter extension of the original theorem’s arbitrary-positive-success phrasing is claimed here. Checked the journal’s actual September2024 publication dates via publisher-deposited metadata and the author’s current publication list. No independent proof audit.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='Resolves the worst-case communication cost of materializing algorithmic mutual information as a secret key, including independent private randomness. Existing score retained.',assessed_on=DATE),review_note='Recovered the secret-key lower-bound task and distinguished public communication from public coins. Marked the historical question resolved using the follow-up’s explicit answer, with precise theorem scope and revision dates.',working_summary=dict(sentences=['Two parties hold correlated strings and communicate publicly to create a shared secret.','The original question asks whether the known worst-case communication lower bound survives independent private randomness.','Gürpınar and Romashchenko answered the bounded-error secret-key question in 2020; their expanded 2024 result removes the cap on random bits.','Some input pairs require about min{C(x|y),C(y|x)} bits even for much shorter secret keys.','The result is a worst-case statement with a supplied complexity profile, not a lower bound for every pair of correlated strings.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','original_full','solution','solution_full'])),notes=['Recovered plain Kolmogorov complexity, exact supplied public profile, private coins and transcript secrecy.','Matched the follow-up’s explicit resolution and its worst-case hard-input scope.','Distinguished >1/2 bounded-error theorem from literal arbitrary-positive-success wording, without asserting a verbatim all-parameter extension.','Checked 2020 polynomial randomness versus 2024 unrestricted version and actual September2024 journal metadata.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2004.13411','https://www.lirmm.fr/~romashchen/papers.html','https://api.crossref.org/works/10.1145/3665163'])
